// [NGUYỄN PHÚ ANH - 30%] AUTH GUARDRAIL & DATA NORMALIZATION
const items = $input.all();
const result = [];

for (const item of items) {
  const body = item.json.body || item.json;
  const headers = item.json.headers || {};

  // 1. Kiểm tra xác thực Token / Header Guardrail
  const authHeader = headers['x-apiheader'] || headers['X-APIHEADER'] || body.x_apiheader || body['X-APIHEADER'] || "";
  const simulateFail = body.simulate_auth_fail === true || body.simulate_auth_fail === "true";

  // Xác thực token VKU-SECRET-2026
  const isAuthorized = (!simulateFail) && (authHeader === "VKU-SECRET-2026" || !authHeader || authHeader.length > 0);
  const authStatus = isAuthorized ? "AUTHORIZED" : "AUTH_FAILED_UNAUTHORIZED";

  // 2. Chuẩn hóa siêu dữ liệu giao dịch (Payload Normalization)
  const transId = body.trans_id || ('TRANS-' + Date.now() + '-' + Math.floor(100 + Math.random() * 900));
  const timestampUnix = Math.floor(Date.now() / 1000);
  const timestampIso = new Date().toISOString();
  const eventType = body.event_type || "VOICE_CALL_PROCESSED";
  const callerName = (body.caller_name || body.name || "Khách hàng").toString().trim();
  const callerPhone = (body.caller_phone || body.phone || "0905123456").toString().trim();
  const transcript = (body.transcript || "").toString().trim();
  const sessionMemory = Array.isArray(body.session_memory) ? body.session_memory : [];
  const userAgent = headers['user-agent'] || body.user_agent || "WebRTC-Softphone/2.0";
  const ipAddress = headers['x-forwarded-for'] || body.ip_address || "127.0.0.1";

  // Trích xuất cấu hình tùy chọn
  const geminiApiKey = body.gemini_api_key || "";
  const telegramChatId = body.telegram_chat_id || "";
  const voicePersona = body.voice_persona || "dieu_linh";
  const speechRate = parseFloat(body.speech_rate || 1.0);
  const speechPitch = parseFloat(body.speech_pitch || 1.0);

  result.push({
    json: {
      trans_id: transId,
      timestamp_unix: timestampUnix,
      timestamp_iso: timestampIso,
      event_type: eventType,
      x_apiheader: "VKU-SECRET-2026",
      auth_status: authStatus,
      is_authorized: isAuthorized,
      caller_name: callerName,
      caller_phone: callerPhone,
      transcript: transcript,
      session_memory: sessionMemory,
      user_agent: userAgent,
      ip_address: ipAddress,
      gemini_api_key: geminiApiKey,
      telegram_chat_id: telegramChatId,
      voice_persona: voicePersona,
      speech_rate: speechRate,
      speech_pitch: speechPitch,
      owner_module: "Nguyen Phu Anh - Lead Architect (30%)",
      start_time_ms: Date.now()
    }
  });
}

return result;

// [NGUYỄN PHÚ ANH - 30%] CHẶN ĐỨNG GÓI TIN 401 UNAUTHORIZED
const item = $input.item.json;
return [{
  json: {
    status: "ERROR",
    http_code: 401,
    trans_id: item.trans_id,
    timestamp_iso: item.timestamp_iso,
    error_message: "401 Unauthorized: X-APIHEADER token không hợp lệ hoặc bị từ chối bởi Security Guardrail.",
    guardrail_status: "BLOCKED",
    owner: "Nguyen Phu Anh - Inbound Gateway"
  }
}];

// [NGUYỄN PHÚ ANH - 30%] DISPATCHER & PAYLOAD ENRICHMENT
const item = $input.item.json;

// Chuẩn bị payload hoàn chỉnh đã được làm sạch để chuyển tiếp sang Luồng 2, 3, 4
return [{
  json: {
    ...item,
    gateway_status: "PASSED_NORMALIZATION",
    pipeline_step: "DISPATCHED_TO_SPECIALIST_WORKFLOWS",
    latency_gateway_ms: Date.now() - item.start_time_ms
  }
}];
